#include "helpers/PolarGridHelper.h"
#include "math/JSNumberMath.h"
#include <numbers>
namespace {std::shared_ptr<BufferGeometry> createGeometry(double radius,double sectors,double rings,double divisions,const JSValue& first,const JSValue& second){const auto color1=Helper_detail::color(first),color2=Helper_detail::color(second);std::vector<double> vertices,colors;const auto pushColor=[&](const Color& c){colors.insert(colors.end(),{c.r,c.g,c.b});};if(sectors==INFINITY||rings==INFINITY||divisions==INFINITY)throw JSRangeError("PolarGridHelper infinite divisions do not terminate");if(sectors>1)for(double i=0;i<sectors;++i){const double v=(i/sectors)*(std::numbers::pi*2);vertices.insert(vertices.end(),{0,0,0,JSNumberMath::sin(v)*radius,0,std::cos(v)*radius});const auto& c=std::fmod(i,2)!=0?color1:color2;pushColor(c);pushColor(c);}for(double i=0;i<rings;++i){const auto& c=std::fmod(i,2)!=0?color1:color2;const double r=radius-(radius/rings*i);for(double j=0;j<divisions;++j){double v=(j/divisions)*(std::numbers::pi*2);vertices.insert(vertices.end(),{JSNumberMath::sin(v)*r,0,std::cos(v)*r});pushColor(c);v=((j+1)/divisions)*(std::numbers::pi*2);vertices.insert(vertices.end(),{JSNumberMath::sin(v)*r,0,std::cos(v)*r});pushColor(c);}}auto result=Helper_detail::geometry(vertices);result->setAttribute("color",std::make_shared<Float32BufferAttribute>(colors,3));return result;}}
PolarGridHelper::PolarGridHelper(double radius,double sectors,double rings,double divisions,HelperColor color1,HelperColor color2):LineSegments(createGeometry(radius,sectors,rings,divisions,color1.value,color2.value),Helper_detail::lineMaterial({},true)){type="PolarGridHelper";}
std::shared_ptr<Object3D> PolarGridHelper::clone(bool recursive)const{auto result=std::make_shared<PolarGridHelper>();result->copy(*this,recursive);return result;}
void PolarGridHelper::dispose(){LineSegments::dispose();Helper_detail::disposeGeometry(geometry);Helper_detail::disposeMaterial(material);}
